for _ in range(int(input())):
	(n, k) = map(int, input().split())
	ans = '00' * (n // 2) + '0' * (n % 2)
	ans = list(ans)
	qry = []
	for i in range(k):
		(x, y) = map(int, input().split())
		qry.append([x, y])
	qry.sort(key=lambda x: x[1] - x[0])
	for i in range(k):
		x = qry[i][0]
		y = qry[i][1]
		mauka = 0
		for i in range(x, y + 1):
			if mauka == 0 and ans[i] == '0':
				ans[i] = '('
			elif mauka == 1 and ans[i] == '0':
				ans[i] = ')'
			mauka = 1 - mauka
	for i in range(n):
		if ans[i] == '0' and i % 2:
			ans[i] = ')'
		elif ans[i] == '0' and i % 2 == 0:
			ans[i] = '('
	print(*ans, sep='')
